"""Prepare all eight primary-source StringTie role reviews without applying catalog changes."""
import argparse
import gzip
import hashlib
import json
from pathlib import Path
import sys
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'tools/literature'))
from catalog_fixed_cohort import verify_fixed_cohort
from collect_omics_review import paragraphs, validate_supporting_evidence

CONTENT = {
 'P101': dict(version='2.1.7', summary='Assembled transcript models from HISAT2 RNA-seq alignments with StringTie2 2.1.7 defaults as transcriptome evidence for MAKER-based genome annotation.', scope='The reported transcript-sequence wording does not specify an additional FASTA-extraction command. The adapter produces original GTF models; alignment, sequence extraction, MAKER, ab initio models and downstream annotation are separate. No exact whole-paper reference/input population is supplied.', roles=[dict(operation='ASSEMBLE', version='2.1.7', settings='reported defaults')]),
 'P102': dict(version='1.3.6', summary='Calculated gene or transcript TPM with StringTie 1.3.6 defaults after HISAT2 alignment and separate SAMtools filtering of low-MAPQ, nonunique and unmapped reads.', scope='The primary paragraph explicitly reports 1.3.6 despite the earlier automated null-version extraction. Guide and exact assembly/estimation command are unstated; do not infer -e or assign the preceding SAMtools filters to StringTie. Original1.3.6 abundance behavior remains distinct from later editions.', roles=[dict(operation='TPM_FROM_GENOMIC_ALIGNMENTS', version='1.3.6', settings='reported defaults; exact assembly/estimation command and guide unstated')]),
 'P109': dict(version='1.3.0', summary='Reported using StringTie 1.3.0 to extract mapping states after HISAT2 RNA-seq alignment during annotation of repeat-masked grape haplotypes.', scope='The literal mapping states wording is methodologically unclear: StringTie is not relabeled as the aligner, and no exact assembly, abundance or mapping-state extraction command is inferred. BRAKER, PASA, MAKER, AUGUSTUS and TE annotation remain separate. Exact1.3.0 is available, but this unclear source role is not claimed as reproduced.', roles=[dict(operation='UNCLEAR_REPORTED_MAPPING_STATES', version='1.3.0', settings='not printed; preserve ambiguity')]),
 'P110': dict(version=None, summary='Used StringTie for gene-model TPM across species after HISAT2 alignment; separately predicted transcript models with StringTie2.1.2 and combined StringTie/Trinity models through Mikado and PASA for annotation updates.', scope='The primary TPM paragraph gives no StringTie edition or exact quantification command. The separately reported2.1.2 belongs to transcript-model prediction and is not assigned to TPM. Kallisto estimated counts/DESeq2 differential expression and deepTools track generation remain separate; Trinity, GMAP, Mikado, Augustus, Liftoff and PASA are not StringTie options.', roles=[dict(operation='TPM_FROM_GENOMIC_ALIGNMENTS', version=None, settings='edition and exact command unstated'), dict(operation='ASSEMBLE', version='2.1.2', settings='transcript-model prediction; HISAT2 -dta/intron settings belong to the aligner'), dict(operation='ANNOTATION_EVIDENCE', version='2.1.2', settings='as-above StringTie/Trinity models supplied to separate Mikado/PASA workflow')]),
 'P171': dict(version='3.0.0', summary='Assembled STAR RNA-seq alignments with StringTie3.0.0 using reported -m150 -t -f0.3 -rf; also merged RNA-seq/Iso-seq transcript assemblies and later combined transcriptome-derived/homology annotation evidence.', scope='The literal -rf fails in all seven retained original editions; it is never silently corrected or claimed reproduced. Explicit --rf is a separate documented control supported by six editions, including3.0.0. The first merge reports -m150 but omits the complete merge invocation; the later combination with cuffcompare also omits exact commands. Iso-seq mapping/collapse, GMAP, cuffcompare, TransDecoder, Augustus and GeneMark are separate.', roles=[dict(operation='ASSEMBLE', version='3.0.0', reported_flags=['-m','150','-t','-f','0.3','-rf'], discrepancy='literal -rf rejected by all seven originals; explicit documented --rf remains separate'), dict(operation='MERGE', version='3.0.0', reported_flags=['-m','150'], settings='complete invocation unstated'), dict(operation='ANNOTATION_EVIDENCE_COMBINATION', version='3.0.0', settings='combination with cuffcompare; complete invocation unstated')]),
 'P183': dict(version=None, summary='Assembled STAR alignments with a supplied GENCODE guide using StringTie -G, then combined sample transcript models with StringTie --merge for lncRNA discovery.', scope='StringTie edition and remaining parameters are unstated. The source names hg19 alignment together with GENCODEv38; exact compatible reference/guide resources remain unresolved and are not silently relabeled. The adjacent StringTie GffCompare wording describes a separate comparison tool, not this adapter. BlastX/CPC2 filtering and RNA-SeQC2.3.5 expression estimation are separate; their counts/TPM are not attributed to StringTie.', roles=[dict(operation='ASSEMBLE', version=None, reported_flags=['-G'], settings='exact edition and guide resource compatibility unresolved'), dict(operation='MERGE', version=None, reported_flags=['--merge'], settings='exact edition and remaining options unstated'), dict(operation='SEPARATE_GFFCOMPARE', version=None, settings='retain named source paragraph without attributing GffCompare to this adapter')]),
 'P223': dict(version=None, summary='Included StringTie in an unspecified HISAT2/StringTie/Ballgown short-read RNA-seq workflow on GRCh38/hg38 iNeuron data.', scope='The combined aligned and mapped wording does not identify a precise StringTie command or edition. Do not relabel StringTie as the aligner or claim Ballgown differential testing. Salmon-generated counts, edgeR differential expression, biomaRt identifiers and Rsubread junction counts are separate steps.', roles=[dict(operation='UNSPECIFIED_HISAT2_STRINGTIE_BALLGOWN_WORKFLOW', version=None, settings='exact StringTie command/edition unstated')]),
 'P248': dict(version='2.2.1', summary='Assembled strand-specific RNA-seq alignments into transcripts with StringTie2.2.1 as evidence for protein-coding gene annotation.', scope='The exact StringTie command and strand convention are not printed; strand-specific data do not justify inventing --rf or --fr. BRAKER2 intron hints, GenomeThreader homology, EVidenceModeler model choice/segment settings, repeat-overlap filtering, DIAMOND, InterPro and KEGG annotation remain separate.', roles=[dict(operation='ASSEMBLE', version='2.2.1', settings='exact command and strand convention unstated')])
}

def digest(raw): return hashlib.sha256(raw).hexdigest()
def main():
    parser = argparse.ArgumentParser(description=__doc__); parser.add_argument('--out', type=Path, required=True); args = parser.parse_args(); out = args.out.resolve()
    assert out.is_relative_to((ROOT / 'build/literature-review/stringtie-runtime').resolve()) and not out.exists()
    data = ROOT / 'docs/literature/omics-2023-2026'; paths = [data / n for n in ['papers.json','tool-inventory.json','summary.json','catalog-enrichment.json','SHA256SUMS']] + [ROOT / 'tools/literature/reviewed-uses.json',ROOT / 'tools/literature/tool-registry.json']
    before = {str(p):p.read_bytes() for p in paths}; papers=json.loads((data/'papers.json').read_bytes()); verify_fixed_cohort(ROOT,data,papers)
    registry=json.loads((ROOT/'tools/literature/tool-registry.json').read_bytes()); reviews=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes()); assert len(registry)==425 and len(reviews['reviews'])==819 and not any(r['tool_id']=='stringtie' for r in reviews['reviews'])
    census=[];drafts=[]
    for paper in papers:
        raw=gzip.decompress((ROOT/'build/literature-review/xml'/(paper['pmcid']+'.xml.gz')).read_bytes()); assert digest(raw)==paper['xml_sha256']; ps=paragraphs(ET.fromstring(raw))
        selected=[t for t in paper['tools'] if t['tool_id']=='stringtie']; census.append(dict(paper_id=paper['paper_id'],xml_sha256=paper['xml_sha256'],selected=bool(selected)))
        if not selected: continue
        assert len(selected)==1 and paper['paper_id'] in CONTENT
        spec=CONTENT[paper['paper_id']];anchor=next(p for p in ps if p['paragraph_index']==selected[0]['evidence_paragraph_index']);assert digest(anchor['text'].encode())==selected[0]['evidence_paragraph_sha256']
        import re
        named=[p for p in ps if re.search(r'(?<![A-Za-z0-9_])StringTie(?:2)?(?![A-Za-z0-9_])',p['match_text'],re.I)]
        supporting=[dict(paragraph_index=p['paragraph_index'],section=p['section'],paragraph_sha256=digest(p['text'].encode())) for p in named if p['paragraph_index']!=anchor['paragraph_index']]
        review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='stringtie',evidence_paragraph_sha256=digest(anchor['text'].encode()),use_summary=spec['summary'],implementation_scope_note=spec['scope'],version_reported_near_name=spec['version'],usage_context='analysis-method-description',supporting_evidence=supporting)
        validate_supporting_evidence(ps,[review],{r['id']:r for r in registry});drafts.append(dict(paper_id=paper['paper_id'],review=review,source_roles=spec['roles'],xml_sha256=paper['xml_sha256'],primary_paragraph_index=anchor['paragraph_index']))
    assert len(drafts)==8 and sum(len(d['review']['supporting_evidence']) for d in drafts)==5
    destination=ROOT/'tools/literature/stringtie-use-reviews.json'; assert not destination.exists(); destination.write_text(json.dumps(drafts,indent=2,ensure_ascii=False)+'\n',encoding='utf-8',newline='\n')
    assert all(p.read_bytes()==before[str(p)] for p in paths);out.mkdir();result=dict(status='prepared-eight-primary-source-StringTie-reviews-not-applied',source_papers_scanned=250,reviewed_papers=8,named_paragraphs=13,supporting_pointers=5,cohort_unchanged=True,existing_819_reviews_unchanged=True,catalog_unchanged=True,P102_version_corrected_in_draft_only='1.3.6',P110_TPM_edition_remains_unspecified=True,P109_mapping_states_remains_unclear=True,P171_literal_rf_failure_retained=True,P183_reference_build_compatibility_unresolved=True,draft=dict(path=destination.relative_to(ROOT).as_posix(),bytes=destination.stat().st_size,sha256=digest(destination.read_bytes())),source_census=census,implementation_promoted=False)
    (out/'VALIDATION.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps({k:v for k,v in result.items() if k!='source_census'}))

if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable complete source checks')
    main()
